]

def rotate90(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [[0]*rows for _ in range(cols)]
    for r in range(rows):
        for c in range(cols):
            result[c][rows-1-r] = grid[r][c]
    return result

